  "inlineSchema": "// prisma/schema.prisma\n// FactuLogin v4.0 — PostgreSQL + Prisma ORM\n// Migrado desde MongoDB + Mongoose (dos clusters) a una sola base de datos relacional.\n//\n// Ventajas de esta migración:\n//   - Un único cluster PostgreSQL (más simple, menos costos)\n//   - Relaciones FK con integridad referencial garantizada por el motor\n//   - Prisma genera tipos TypeScript/JS automáticamente\n//   - Migrations versionadas (git-friendly)\n//   - Query engine nativo compilado en Rust (rendimiento superior a Mongoose)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── USUARIOS ───────────────────────────────────────────────────────────────\n\nmodel User {\n  id            String   @id @default(cuid())\n  name          String   @db.VarChar(120)\n  email         String   @unique @db.VarChar(255)\n  password_hash String\n  profile_image String?\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  // Relaciones\n  notifications Notification[]\n  invoices      Invoice[]\n  events        UserEvent[]\n  orders        Order[]\n\n  @@index([email])\n  @@map(\"users\")\n}\n\nmodel Notification {\n  id         String   @id @default(cuid())\n  user_id    String\n  message    String   @db.VarChar(500)\n  read       Boolean  @default(false)\n  created_at DateTime @default(now())\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@map(\"notifications\")\n}\n\nmodel Invoice {\n  id          String   @id @default(cuid())\n  user_id     String\n  description String   @db.VarChar(300)\n  total       Decimal  @db.Decimal(12, 2)\n  created_at  DateTime @default(now())\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@map(\"invoices\")\n}\n\nmodel UserEvent {\n  id         String   @id @default(cuid())\n  user_id    String\n  action     String   @db.VarChar(100)\n  detail     String?  @db.VarChar(300)\n  ip         String?  @db.VarChar(45)\n  created_at DateTime @default(now())\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@map(\"user_events\")\n}\n\n// ─── NEGOCIO ─────────────────────────────────────────────────────────────────\n\nmodel Client {\n  id         String   @id @default(cuid())\n  name       String   @db.VarChar(180)\n  document   String   @unique @db.VarChar(30)\n  phone      String   @db.VarChar(20)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  orders Order[]\n\n  @@index([document])\n  @@map(\"clients\")\n}\n\nmodel Company {\n  id         String   @id @default(cuid())\n  name       String   @db.VarChar(180)\n  nit        String   @unique @db.VarChar(30)\n  phone      String   @db.VarChar(20)\n  address    String   @db.VarChar(300)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  orders Order[]\n\n  @@index([nit])\n  @@map(\"companies\")\n}\n\nmodel Product {\n  id         String   @id @default(cuid())\n  name       String   @db.VarChar(180)\n  brand      String   @default(\"\") @db.VarChar(100)\n  price      Decimal  @db.Decimal(12, 2)\n  stock      Int      @default(0)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  order_items OrderItem[]\n\n  @@index([name])\n  @@map(\"products\")\n}\n\nmodel Order {\n  id         String   @id @default(cuid())\n  user_id    String?\n  client_id  String\n  company_id String\n  total      Decimal  @db.Decimal(12, 2)\n  created_at DateTime @default(now())\n\n  user    User?       @relation(fields: [user_id], references: [id], onDelete: SetNull)\n  client  Client      @relation(fields: [client_id], references: [id])\n  company Company     @relation(fields: [company_id], references: [id])\n  items   OrderItem[]\n\n  @@index([user_id])\n  @@index([created_at(sort: Desc)])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id           String  @id @default(cuid())\n  order_id     String\n  product_id   String\n  product_name String  @db.VarChar(180)\n  quantity     Int\n  price        Decimal @db.Decimal(12, 2)\n  pct_desc     Decimal @default(0) @db.Decimal(5, 4)\n  subtotal     Decimal @db.Decimal(12, 2)\n\n  order   Order   @relation(fields: [order_id], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [product_id], references: [id])\n\n  @@index([order_id])\n  @@map(\"order_items\")\n}\n",
